#include <vector>
#include <complex>
#include <algorithm>
#include <omp.h>

void sortComplexByMagnitude(std::vector<std::complex<double>> &x) {
    const std::size_t n = x.size();
    if (n < 2) return;

    // Parallel odd-even transposition sort:
    // Deterministic, in-place, and safe under any OpenMP thread count.
    for (std::size_t phase = 0; phase < n; ++phase) {
        const std::size_t start = phase % 2; // even phase: 0, odd phase: 1

        #pragma omp parallel for default(none) shared(x, n, start)
        for (std::ptrdiff_t i = static_cast<std::ptrdiff_t>(start);
             i + 1 < static_cast<std::ptrdiff_t>(n);
             i += 2) {
            const double mi = std::norm(x[static_cast<std::size_t>(i)]);
            const double mj = std::norm(x[static_cast<std::size_t>(i + 1)]);
            if (mi > mj) {
                std::swap(x[static_cast<std::size_t>(i)], x[static_cast<std::size_t>(i + 1)]);
            }
        }
        // Implicit barrier at end of omp for ensures phase completion.
    }
}
